css:
.ds-phosphor { --ds-cover-bg: var(--ds-glass); }
.ds-phosphor .ds-section h2, .ds-phosphor .ds-cover-name { font-family: var(--font-display); }
.ds-phosphor .ds-chip { border-radius: 0; }
.ds-phosphor .p-tint { fill: var(--ds-green-soft); } .ds-phosphor .p-dot rect { fill: var(--ds-green); } .ds-phosphor .p-green { fill: var(--ds-green); } .ds-phosphor .p-amber { fill: var(--ds-amber); } .ds-phosphor .p-sunk { fill: var(--ds-glass-sunk); }
.ds-phosphor .p-rim { fill: none; stroke: var(--ds-edge); stroke-width: 1; } .ds-phosphor .p-cursor { fill: var(--ds-green); }
.ds-phosphor .p-glow { filter: drop-shadow(0 0 6px rgba(61,255,122,.6)); } .ds-phosphor .p-glow-a { filter: drop-shadow(0 0 6px rgba(255,176,0,.7)); }
.light .ds-phosphor .p-glow, .light .ds-phosphor .p-glow-a { filter: none; }
.ds-phosphor .p-svg-log { font-family: var(--font-mono); font-size: 12px; letter-spacing: .06em; fill: var(--ds-ink); } .ds-phosphor .p-svg-prompt { font-family: var(--font-mono); font-size: 22px; font-weight: 700; fill: var(--ds-green); } .ds-phosphor .p-svg-cmd { font-family: var(--font-mono); font-size: 22px; fill: var(--ds-ink); }
.ds-phosphor .p-amber-fill { fill: var(--ds-amber); } .ds-phosphor .p-muted-fill { fill: var(--ds-ink-muted); } .ds-phosphor .p-on-green { fill: var(--ds-on-green); font-weight: 700; }
@keyframes p-blink { 50% { opacity: 0; } } .ds-phosphor .p-blink { animation: p-blink 1s steps(1) infinite; } @media (prefers-reduced-motion: reduce) { .ds-phosphor .p-blink { animation: none; } }
.ds-phosphor .p-muted { color: var(--ds-ink-muted); } .ds-phosphor .p-amber-ink { color: var(--ds-amber); }
.ds-phosphor .p-btn { font-family: var(--font-mono); font-size: 14px; line-height: 20px; padding: 9px 14px; border: 1px solid var(--ds-edge); background: transparent; color: var(--ds-ink); cursor: pointer; transition: box-shadow 120ms linear, background 120ms linear; }
.ds-phosphor .p-btn:hover { box-shadow: var(--ds-glow); background: var(--ds-green-soft); } .ds-phosphor .p-btn:focus-visible { outline: 1px solid var(--ds-amber); outline-offset: 2px; box-shadow: var(--ds-glow-amber); }
.ds-phosphor .p-btn-primary { background: var(--ds-green); color: var(--ds-on-green); font-weight: 700; } .ds-phosphor .p-btn-amber { border-color: var(--ds-amber); color: var(--ds-amber); box-shadow: var(--ds-glow-amber); }
.ds-phosphor .p-tag { display: inline-flex; gap: 6px; align-items: center; padding: 2px 8px; border: 1px solid var(--ds-line); font-family: var(--font-mono); font-size: 12px; letter-spacing: .06em; color: var(--ds-ink-muted); }
.ds-phosphor .p-pass { color: var(--ds-green-ink); border-color: var(--ds-green); } .ds-phosphor .p-run { color: var(--ds-amber); border-color: var(--ds-amber); box-shadow: var(--ds-glow-amber); } .ds-phosphor .p-fail { color: var(--ds-negative); border-color: var(--ds-negative); }
.ds-phosphor .p-stat { display: grid; gap: 6px; padding: 18px 20px; border: 1px solid var(--ds-edge); background: var(--ds-glass-raised); min-width: 200px; }
.ds-phosphor .p-stat-live { border-color: var(--ds-amber); box-shadow: var(--ds-glow-amber); } .ds-phosphor .p-stat-live .t-numeral { color: var(--ds-amber); }
.ds-phosphor .p-delta { font-size: 13px; color: var(--ds-ink-muted); } .ds-phosphor .p-up { color: var(--ds-green-ink); }
.ds-phosphor .p-callout { padding: 12px 14px; border-left: 2px solid var(--ds-line); font-family: var(--font-mono); font-size: 14px; line-height: 1.5; background: var(--ds-glass-sunk); }
.ds-phosphor .p-callout-pass { border-color: var(--ds-green); background: var(--ds-green-soft); } .ds-phosphor .p-callout-warn { border-color: var(--ds-amber); background: var(--ds-amber-soft); } .ds-phosphor .p-callout-fail { border-color: var(--ds-negative); background: var(--ds-negative-soft); }
.ds-phosphor .p-panel { border: 1px solid var(--ds-edge); background: var(--ds-glass-raised); padding: 18px 20px; min-width: 0; } .ds-phosphor .p-panel > .t-label { display: block; margin-bottom: 12px; color: var(--ds-ink-muted); }
.ds-phosphor .p-panel-live { border-color: var(--ds-amber); box-shadow: var(--ds-glow-amber); }
.ds-phosphor .p-panel-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 12px; }
.ds-phosphor .p-log { margin: 0 0 12px; padding: 12px; background: var(--ds-glass-sunk); border: 1px solid var(--ds-line); font-family: var(--font-mono); font-size: 13px; line-height: 20px; overflow-x: auto; color: var(--ds-ink); }
.ds-phosphor .p-sample { background: var(--ds-glass); padding: 40px 20px 64px; border-top: 1px solid var(--ds-edge); border-bottom: 1px solid var(--ds-edge); }
.ds-phosphor .p-sample-in { max-width: 1100px; margin: 0 auto; }
.ds-phosphor .p-sample-top { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding-bottom: 12px; border-bottom: 1px solid var(--ds-line); }
.ds-phosphor .p-prompt-line { margin: 28px 0 0; font-family: var(--font-mono); font-size: 18px; color: var(--ds-ink-muted); } .ds-phosphor .p-prompt { color: var(--ds-green); font-weight: 700; margin-right: 8px; }
.ds-phosphor .p-sample-h { margin-top: 12px; max-width: 20ch; } .ds-phosphor .p-sample-lede { margin-top: 16px; max-width: 60ch; color: var(--ds-ink-muted); }
.ds-phosphor .p-sample-stats { display: grid; gap: 16px; margin-top: 32px; } .ds-phosphor .p-sample-grid { display: grid; gap: 16px; margin-top: 16px; } .ds-phosphor .p-sample-grid + .p-panel { margin-top: 16px; }
@container (min-width: 760px) { .ds-phosphor .p-sample { padding: 56px 40px 80px; } .ds-phosphor .p-sample-stats { grid-template-columns: 1fr 1fr 1fr; } .ds-phosphor .p-sample-grid { grid-template-columns: 1fr 1fr; } }

.ds-phosphor { --ds-hand-ink: var(--ds-green); --ds-hand-fill: var(--ds-green); --ds-hand-fill2: var(--ds-amber); --ds-hand-muted: var(--ds-glass-sunk); --ds-hand-ground: var(--ds-glass-raised); --ds-hand-stroke: 1.5; --ds-hand-cap: square; --ds-hand-bg: var(--ds-glass);
  --ds-tpl-edge: 1px solid var(--ds-edge); --ds-tpl-radius: 0; --ds-tpl-rule: 1px solid var(--ds-line); --ds-tag-radius: 0; --ds-slide-bg: var(--ds-glass-raised); --ds-slide-title-bg: var(--ds-glass-sunk); --ds-slide-title-fg: var(--ds-green-ink); --ds-slide-split-a: var(--ds-green); --ds-slide-split-a-fg: var(--ds-on-green); --ds-slide-split-b: var(--ds-amber); --ds-slide-split-b-fg: var(--ds-on-amber); --ds-hero-bg: var(--ds-glass-sunk); }
.ds-phosphor .h-fill { opacity: .25; } .ds-phosphor .h-fill2 { opacity: .9; } .ds-phosphor .h-glow .h-ink { stroke: var(--ds-green); }
.light .ds-phosphor .h-glow { display: none; } .light .ds-phosphor .h-fill { opacity: .18; }
.ds-phosphor .h-num { font-family: var(--font-mono); font-weight: 500; fill: var(--ds-green-ink); } .ds-phosphor .h-text { fill: var(--ds-ink-muted); }
.ds-phosphor .ds-hand-art, .ds-phosphor .ds-tpl-figure { background-image: radial-gradient(var(--ds-line) 1px, transparent 1px); background-size: 16px 16px; }
.ds-phosphor .ds-tpl-tag { font-family: var(--font-mono); text-transform: none; letter-spacing: .06em; border: 1px solid var(--ds-line); background: transparent; }
.ds-phosphor .ds-tpl-tag.is-ok { border-color: var(--ds-green); background: transparent; } .ds-phosphor .ds-tpl-tag.is-warn { border-color: var(--ds-amber); background: transparent; box-shadow: var(--ds-glow-amber); } .ds-phosphor .ds-tpl-tag.is-bad { border-color: var(--ds-negative); background: transparent; }
.ds-phosphor .ds-tpl-stage-title .ds-tpl-slide-h { color: var(--ds-green-ink); } .ds-phosphor .ds-tpl-stage-title .ds-tpl-stage-foot { border-top-color: var(--ds-line); }
.ds-phosphor .ds-tpl-dropcap { color: var(--ds-green-ink); } .ds-phosphor .ds-tpl-pull { border-top-color: var(--ds-green); }
.ds-phosphor .ds-tpl-kpi, .ds-phosphor .ds-tpl-tile, .ds-phosphor .ds-tpl-step { background: var(--ds-glass-raised); }

.ds-phosphor .h-fill2 { opacity: .45; } .ds-phosphor .h-text { fill: var(--ds-ink); }

.ds-phosphor .ds-tpl-tile { overflow-x: auto; }
